using var conn = new SqlConnection(cs);
conn.Open();
using var tx = conn.BeginTransaction();
try {
    foreach (var r in uow.Added)   Exec(conn, tx, insertSql, r);
    foreach (var r in uow.Dirty)   Exec(conn, tx, updateSql, r);
    tx.Commit();
    uow.Clear();
} catch { tx.Rollback(); throw; }   // or discard the uow entirely
